class IssuerClients {
    private final ConcurrentMap<String, IssuerClient> clients = new ConcurrentHashMap<>();

    IssuerClient clientFor(String issuerId) {
        // connect runs at most once per absent key; other callers for that key wait for it
        return clients.computeIfAbsent(issuerId, this::connect);
    }

    private IssuerClient connect(String issuerId) {
        return new IssuerClient(issuerId);   // opens a connection
    }
}

kotlin.src:
class IssuerClients {
    private val clients = ConcurrentHashMap<String, IssuerClient>()

    // looks the same, isn't: two threads can both run connect() for one key
    fun clientForRacy(issuerId: String): IssuerClient =
        clients.getOrPut(issuerId) { connect(issuerId) }

    // the same guarantee as Java: call the JDK method
    fun clientFor(issuerId: String): IssuerClient =
        clients.computeIfAbsent(issuerId) { connect(it) }

    private fun connect(issuerId: String): IssuerClient = IssuerClient(issuerId)   // opens a connection
}

