public class FraudRulesProvider {
    @Inject RulesClient rulesClient;
    private volatile FraudRules rules;                  // 1. volatile: the fast path needs the edge

    public FraudRules rules() {
        FraudRules r = rules;                           // 2. fast path: one volatile read
        if (r != null) return r;
        synchronized (this) {                           // 3. slow path: one download at a time
