public final class BinTable {
    private BinTable() { /* load the table */ }

    private static final class Holder {
        static final BinTable INSTANCE = new BinTable();   // built once, under the class-init lock
    }

    public static BinTable instance() { return Holder.INSTANCE; }
}

public final class IssuerGateway {
    private final Vault vault;
    private volatile SigningKey key;   // volatile: the fast path reads it without the lock

    public IssuerGateway(Vault vault) { this.vault = vault; }

    public SigningKey signingKey() {
        SigningKey k = key;            // one volatile read
        if (k != null) return k;
        synchronized (this) {
            k = key;                   // check again under the lock
            if (k == null) {
                k = vault.fetch("issuer-signing-key");
                key = k;               // volatile write publishes the finished key
            }
            return k;
        }
    }
}

